"""Current-assistant semantic review; independent human adjudication remains absent."""
from isc4_open import read,save,freeze,sha
from isc5_run import OUT

def main():
    q=read(OUT/'review_queue.json')
    assert len(q)==158 and q[32]['claim']=='B is scheduled to fly to Paris with A.' and q[157]['dialogue_id']=='test_987'
    decision={}
    def put(indices,kind,refs=(),partial=(),grounded=True,reason='',source='consistent',canonical=None):
        for i in indices:
            assert i not in decision
            decision[i]={'verdict':kind,'reference_ids':list(refs),'partial_reference_ids':list(partial),
                'A_grounded':grounded,'source_status':source,'rationale':reason,
                'canonical_id':canonical or (refs[0] if refs else partial[0] if partial else q[i]['review_id'])}
    def match(indices,ref,reason='Equivalent at frozen attribute granularity; checked in full A context.'):
        put(indices,'match',[ref],reason=reason)
    def part(indices,refs,ground=True,reason='',source='consistent'):
        put(indices,'partial',partial=refs,grounded=ground,reason=reason,source=source)
