    part([15,16],['test_260_suitcases','test_260_handbag'],True,'The plural them across A positions supports baggage plurality; exact counts, colors and types are not recovered.')
    put([17],'out_of_scope',reason='Calling A is an observed conversational act under the frozen counting policy.')
    match([18],'test_277_name')
    put([19],'unverified',grounded=False,reason='A compares Dalian and New York; this does not locate B.',source='unverified')
    part([20,21],['test_327_hotel'],False,'A asks whether B is staying; full B confirms a booking, not necessarily a current stay.',source='unverified')
    put([22],'unsupported',grounded=False,reason='I did make a mistake is A\'s admission, wrongly assigned to B.',source='contradicted')
    put([23],'unsupported',grounded=False,reason='A recalls postponing the historical wedding; B suggests celebrating early, not postponing the current celebration.',source='contradicted')
    part([24,27],['test_369_marriage'],False,'Coarse ten-year marriage agrees, but June 20 is the date A later admits was wrong.',source='incorrect_date_qualifier')
    put([25,26],'contested',grounded=False,reason='The accusation of forgetting relies on A\'s incorrect anniversary date, later corrected.',source='contested')
    part([28,29],['test_369_anniversary'],True,'Reported July 20 belief is weaker than the final corrected anniversary; A\'s later acknowledgment supports the date.')
    part([30,31],['test_369_marriage'],True,'Spouse/partnership is supported, but this item alone omits the ten-year duration.')
    match([32],'test_369_trip','Claim plus structured time future (day after tomorrow) recovers the frozen travel plan.')
    match([33,34],'test_375_name')
    put([35],'match',['test_39_profession','test_39_name'],reason='Compound statement split into profession and surname atoms. A\'s class reference corroborates the office question.')
    match([36],'test_39_profession');match([37,38,39],'test_39_teaching');match([40,41],'test_39_name')
    match([42],'test_439_wife')
    part([43],['test_439_wife'],True,'Married is entailed by wife, but does not recover the particular spouse relation as specifically.')
    put([44],'unverified',grounded=False,reason='Calling about unemployment checks does not establish access to private account records.',source='unverified')
    put([45,46,47],'match',['test_468_role'],grounded=False,reason='Full B\'s institutional we supports the service role; A\'s questions alone do not establish the specific institutional authority.')
