    put([49],'out_of_scope',reason='Being asked a favor is not acceptance of the specific mailing plan.')
    put([50,51,52],'unverified',grounded=False,reason='A proposes a joint meal/TV plan, but current B access or precise co-location is not established.',source='unverified')
    put([53],'unsupported',grounded=False,reason='I am hungry is A\'s state; no source statement establishes B is hungry.',source='unverified')
    put([54],'supported_new',reason='A presents a birthday gift to B; full B accepts it. Concrete personal event omitted by the reference.',canonical='test_525_gift')
    match([55],'test_525_name');match([56],'test_525_birthday')
