    put([82],'out_of_scope',grounded=False,reason='A asks for recommendations; this does not reveal a stable personal profile fact about B.')
    put([83,84,85,86,87],'out_of_scope',grounded=False,reason='Generic sales descriptions identify no specific habit, need or fitness value.')
    put([88],'unverified',grounded=False,reason='Madam is an address convention, not independent verification of sex/gender.',source='unverified')
    part([89,90,91],['test_674_membership'],True,'Membership menu followed by Wise decision supports a coarse choice; duration remains unknown. No one-year value is credited.')
    match([92,93],'test_697_wife');match([94,95],'test_697_usa');match([96,97],'test_697_name')
    part([98,99,100,101],['test_697_english'],True,'English knowledge is recovered, but not the proficiency qualifier speaks well.')
