    put([115],'out_of_scope',grounded=True,reason='Finishing an unspecified activity has no individualized value to count.')
    put([116,118],'unverified',grounded=False,reason='Education/training is not specified in visible A; do not invent the completion object.',source='unverified')
    match([119,120],'test_796_english_work','Future professional usefulness of English is preserved; not interpreted as proof of current employment.')
    match([121],'test_806_name')
    put([122,123],'source_supported_new',grounded=None,reason='Full B endorses Movie Salon. A\'s reaction suggests a positive evaluation but exact A-only entailment remains uncertain.',canonical='test_826_store_opinion')
    put([124,128],'unverified',grounded=False,reason='Corrupted phrase what a confidence is not reliable evidence of a psychological trait.',source='unverified')
    part([125],['test_826_renting'],False,'Movie Salon is a rental store; going there to watch films adds an unobserved purpose.',source='unverified')
    put([126],'unsupported',grounded=False,reason='Movie Salon is explicitly a rental store, not the cinema described by the claim.',source='contradicted')
    part([127],['test_826_cinema'],True,'Frequency question reasonably backgrounds some cinema-going; once-in-a-while value remains hidden.')
    put([129,130],'unsupported',grounded=False,reason='Comedy and suspense belong to A\'s list; B\'s preferences are art films and thrillers.',source='contradicted')
    part([131],['test_826_renting'],True,'A\'s later also sign up provides context for B\'s use of the place; exact renting habit remains hidden.')
    match([132,133],'test_826_movies');match([134],'test_826_name')
    put([135],'out_of_scope',reason='Additive wondering about the topic is a conversational mental act, not an individualized profile value.')
    part([136],['test_91_broadcast'],True,'Access to road news is the background of how do you get it; broadcast medium is not recovered here.')
    match([137],'test_91_broadcast','In context all news is the road news topic, not all world news. Confirmatory So question supports a defeasible background inference.')
    put([138,149],'unsupported',grounded=False,reason='The career-versus-family choice primarily concerns the former partner, not B\'s own career.',source='unverified')
    match([139,140,141],'test_926_breakup');match([142,143],'test_926_down','Down/depressed denotes the conversational mood, not a clinical depression diagnosis.')
    match([144],'test_926_success')
    part([145,146],['test_926_breakup'],False,'Former relationship is supported; who actually ended it is not specified.',source='unverified')
    part([147],['test_926_breakup'],True,'Previous female partner is supported, but recent breakup timing is omitted.')
    match([148],'test_926_name')
